   const handler=backfillHandler(db,backfillDeliveryQueue,loadKey,()=>brokerNow,(_db,_q,input)=>normalizedHistoricalGateway({...input,request:async window=>({state:'KNOWN',data:historyDates.filter(date=>date>=window.from&&date<=window.to).map(date=>[date+'T00:00:00+05:30','100','101','99','100','1000'])})}));
   await assert.rejects(handler({runId:queuedRun.id,accessToken:'must-not-be-accepted'}),/INVALID_BACKFILL_PAYLOAD/);
   await dispatchBackfills(db,backfillDeliveryQueue);
