   backfillDeliveryWorker=createWorker(backfillDeliveryName,{backfill:handler});const until=Date.now()+15000;
   while(await restored.getState()!=='completed'&&Date.now()<until)await new Promise(resolve=>setTimeout(resolve,50));
   assert.equal(await restored.getState(),'completed');assert.equal((await syncJobs(db,{runId:queuedRun.id})).items[0].state,'COMPLETE');
