   await assert.rejects(prepareIncremental(db,{...incrementalInput,calendar:[]}),/SYNC_CALENDAR_UNKNOWN/);
   const unknownIncremental=await prepareIncremental(db,{...incrementalInput,id:randomUUID(),calendar:[]});assert.equal(unknownIncremental.state,'UNKNOWN');
   await bindBackfill(db,{...binding,runId:incrementalInput.id},incrementalAt);
   const requests=[];
   const incrementalHandler=backfillHandler(db,backfillDeliveryQueue,loadKey,()=>incrementalAt,(_db,_q,input)=>normalizedHistoricalGateway({...input,request:async window=>{
    requests.push(window);return {state:'KNOWN',data:historyDates.filter(date=>date>=window.from&&date<=window.to).map(date=>[date+'T00:00:00+05:30','100','101','99',date===historyDates.at(-1)?'101':'100','1000'])};
   }}));
   const changed=await incrementalHandler({runId:incrementalInput.id});assert.equal(changed.state,'COMMITTED');assert.equal(changed.report.revised,1);assert.equal(changed.report.unchanged,2);
   assert.deepEqual(requests.map(r=>[r.from,r.to]),[[historyDates.at(-3),historyDates.at(-1)]]);
   assert.equal((await incrementalHandler({runId:incrementalInput.id})).state,'IDLE');assert.equal(requests.length,1);
   assert.equal((await prepareIncremental(db,incrementalInput)).state,'RESUMED');
   assert.equal((await db.candleRevision.findMany({where:{listingId:queuedRun.listingId}})).length,17);
   const incrementalChanges=await db.$queryRaw`SELECT "id" FROM "CandleChangeOutbox" WHERE "id"=${changed.report.changes[0]}::uuid`;
   assert.equal(incrementalChanges.length,1);
   const replayRequest=await receiveCandleChange(db,incrementalChanges[0].id);
   assert.equal(replayRequest.planVersion,2);assert.equal(replayRequest.iteration,'SESSION_ASC');
   assert.deepEqual(replayRequest.stages,['INDICATORS','MARKET_SIGNALS','VCP','SCANS']);
   assert.deepEqual(await receiveCandleChange(db,incrementalChanges[0].id),replayRequest);
